package arnold

import (
	"os"
	"path/filepath"
	"testing"
)

// This fixture was generated by the original Node Store, including its exact
// serialized pending payload and stream metadata. It contains synthetic data.
func TestNodeStateMigratesWithoutReplayingOrRefetchingHistory(t *testing.T) {
	path := filepath.Join(t.TempDir(), "state.sqlite")
	data, e := os.ReadFile("testdata/node-state.sqlite")
	if e != nil {
		t.Fatal(e)
	}
	if e = os.WriteFile(path, data, 0600); e != nil {
		t.Fatal(e)
	}
	s, e := OpenStore(path)
	if e != nil {
		t.Fatal(e)
	}
	defer s.Close()
	taskID := "0123456789abcdef01234567"
	b, e := s.Binding("T1:C1:1", "U1", "engineer-a", "implementation")
	if e != nil || b == nil || b.Task != taskID {
		t.Fatal("lost Node binding", b, e)
	}
	if cursor, _ := s.Cursor(taskID); cursor != "opaque-node-cursor" {
		t.Fatal("lost cursor")
	}
	if done, _ := s.Delivered(taskID, "m:answer:0", 0); !done {
		t.Fatal("lost output receipt")
	}
	m, e := s.Stream(taskID, "turn1")
	if e != nil || m.TS != "123.456" || m.Characters != 23 || m.Started != 1710000000000 {
		t.Fatal("lost stream metadata", m, e)
	}
	pending, e := s.Pending()
	if e != nil || len(pending) != 1 || pending[0].ID != Hash("T1:C1:2") {
		t.Fatal("lost pending receipt", e)
	}
	p := &fakePaddock{tasks: map[string]Task{}}
	var task Task
	task.ID = taskID
	task.Runtime = "openshell"
	task.Status = "running"
	task.Session.Agent = "claude"
	task.Session.ConversationID = "conversation"
	task.Provenance.Identity = "engineer-a"
	task.Provenance.Profile = "implementation"
	p.tasks[taskID] = task
	chat := &fakeChat{contextErr: os.ErrPermission}
	c := configFixture()
	c.Agent = "claude"
	a := &Agent{Config: c, Store: s, Paddock: p, Slack: chat}
	if e = a.Drain(testContext); e != nil {
		t.Fatal(e)
	}
	if len(p.runs) != 0 || len(p.messages) != 1 || p.messages[0].Text != "Current message from U1:\nnew only" || p.messages[0].ID != Hash("T1:C1:2") {
		t.Fatal("migration changed/replayed pending work")
	}
	if chat.contextCalls != 0 {
		t.Fatal("resume refetched Slack history")
	}
	if e = a.Poll(testContext); e != nil {
		t.Fatal(e)
	}
	if len(chat.events) != 0 {
		t.Fatal("previous output replayed")
	}
	if cursor, _ := s.Cursor(taskID); cursor != "opaque-node-cursor" {
		t.Fatal("cursor changed")
	}
	info, e := os.Stat(path)
	if e != nil || info.Mode().Perm() != 0600 {
		t.Fatal("state permissions")
	}
}
